func TestTruncateBody(t *testing.T) {
	t.Parallel()

	const maxBytes = 4096

	cases := []struct {
		name        string
		input       []byte
		wantLen     int
		wantHasTail bool
	}{
		{"empty", nil, 0, false},
		{"under cap", []byte("hello"), 5, false},
		{"at cap", bytes.Repeat([]byte("a"), maxBytes), maxBytes, false},
		{"one over cap", bytes.Repeat([]byte("a"), maxBytes+1), maxBytes + 3, true},
		{"huge body", bytes.Repeat([]byte("a"), maxBytes*8), maxBytes + 3, true},
	}

	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			got := truncateBody(tc.input)
			if len(got) != tc.wantLen {
				t.Fatalf("len = %d, want %d", len(got), tc.wantLen)
			}
			if tc.wantHasTail && !strings.HasSuffix(got, "...") {
				t.Fatalf("want trailing %q", "...")
			}
			if !tc.wantHasTail && strings.HasSuffix(got, "...") {
				t.Fatalf("unexpected trailing %q in %q", "...", got)
			}
		})
	}
}

func TestTruncateBody_UTF8RuneAtBoundary(t *testing.T) {
	t.Parallel()

	// '€' is 3 bytes (0xE2 0x82 0xAC). Place it so the slice at byte 4096 cuts
	// mid-rune; strings.ToValidUTF8 should drop the partial rune cleanly rather
	// than emit U+FFFD or invalid UTF-8.
	prefix := strings.Repeat("a", 4094)
	body := []byte(prefix + "€" + strings.Repeat("b", 100))
	got := truncateBody(body)

	if !utf8.ValidString(got) {
		t.Fatalf("output is not valid UTF-8")
	}
	if strings.ContainsRune(got, utf8.RuneError) {
		t.Fatalf("output contains replacement rune U+FFFD")
	}
	if !strings.HasSuffix(got, "...") {
		t.Fatalf("want trailing %q", "...")
	}
	// Partial rune must be dropped, not replaced: 4094 valid bytes + "...".
	if want := 4094 + 3; len(got) != want {
		t.Fatalf("len = %d, want %d (partial rune should be dropped, not replaced)", len(got), want)
	}
}

func TestRegionRedirectRetriesWithRegionalAPI(t *testing.T) {
	t.Parallel()
	var regional *httptest.Server
	regional = httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/user/stat/file" {
			t.Fatalf("regional path = %s", r.URL.Path)
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"status":0,"ok":true}`))
	}))
	defer regional.Close()

	primary := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"status":-302,"data":{"domains":{"api":"` + regional.URL + `"}}}`))
	}))
	defer primary.Close()

	c := New(&config.Config{BaseURL: primary.URL}, 0, 0)
	data, err := c.GetNoCache(context.Background(), "/user/stat/file", nil)
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(data), `"ok":true`) {
		t.Fatalf("data = %s, want regional success", data)
	}
	if c.BaseURL != regional.URL {
		t.Fatalf("BaseURL = %s, want %s", c.BaseURL, regional.URL)
	}
}

func TestRegionRedirectAtRetryLimitReturnsError(t *testing.T) {
	t.Parallel()

	nextURLs := make([]string, 4)
	servers := make([]*httptest.Server, 4)
	for i := range servers {
		i := i
		servers[i] = httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			w.Header().Set("Content-Type", "application/json")
			_, _ = w.Write([]byte(`{"status":-302,"data":{"domains":{"api":"` + nextURLs[i] + `"}}}`))
		}))
		defer servers[i].Close()
	}
	for i := range servers {
		if i+1 < len(servers) {
			nextURLs[i] = servers[i+1].URL
		} else {
			nextURLs[i] = "https://final-region.plaud.example"
		}
	}

	c := New(&config.Config{BaseURL: servers[0].URL}, 0, 0)
	data, err := c.GetNoCache(context.Background(), "/user/stat/file", nil)
	if err == nil {
		t.Fatalf("GetNoCache() error = nil, data = %s; want regional redirect error", data)
	}
	if !strings.Contains(err.Error(), "regional redirect") {
		t.Fatalf("error = %q, want regional redirect", err.Error())
	}
}
